이벤트: onCompositionStart → () => { composingInput.current = true; }
onCompositionEnd → () => { composingInput.current = false; }
onChange → (event) => setTerminalInput(event.target.value)
onKeyDown → (event) => { if ( event.key !== 'Enter' || event.shiftKey || event.nativeEvent.isComposing || composingInput.current || event.keyCode === 229 ) return; event.preventDefault(); terminalExecution.current?.write( terminalInput.replace(/\r\n?/g, '\n').replaceAll('\n', '\r') + '\r', ); setTerminalInput(''); }
